module benchmark/solution
import std/env (getArgs)
import std/fs (readFile)
import std/string (split, trim, stringToInt)
import std/list (foldl)

func sumLines(lines: [string]) -> int =
  foldl(func(acc: int, line: string) -> int {
    match stringToInt(trim(line)) {
      Some(n) => acc + n,
      None => acc
    }
  }, 0, lines)

export func main() -> () ! {IO, FS, Env} {
  match getArgs() {
    filename :: _ => {
      let contents = readFile(filename);
      println(show(sumLines(split(contents, "\n"))))
    },
    _ => println("0")
  }
}

